import{_ as t,a as n,b as r,c as i,d as s,e as o,f as d,g as a,h as l}from"./chunks/technic-light-runtime.BM1alCex.js";import{_ as u,o as c,c as g,a3 as h}from"./chunks/framework.BlfGB29P.js";const E=JSON.parse('{"title":"Technic","description":"Das externe Technic-Widget-Set installieren und Window – Wall mit Home Assistant verbinden.","frontmatter":{"title":"Technic","description":"Das externe Technic-Widget-Set installieren und Window – Wall mit Home Assistant verbinden."},"headers":[],"relativePath":"projects/grafik-visual-studio/technic.md","filePath":"projects/grafik-visual-studio/technic.md","lastUpdated":1792840662000}'),b={name:"projects/grafik-visual-studio/technic.md"};function m(p,e,f,k,S,z){return c(),g("div",null,[...e[0]||(e[0]=[h('<h1 id="technic" tabindex="-1">Technic <a class="header-anchor" href="#technic" aria-label="Permalink to &quot;Technic&quot;">​</a></h1><p>Ab <strong>Studio 0.1.296</strong> bietet der Thermostat zusätzlich eine zunächst deaktivierte <a href="./ha-quellen-climate">Climate-Steuerung</a>: zwei Sollwerte, Betriebsarten, Presets, Lüfter, Schwenken, Feuchtigkeit und Ein/Aus nach Gerätefähigkeit. Die Widget-Eigenschaften und Laufzeitmeldungen sind DE/EN/FR wählbar; bestehende Einstellungen bleiben gültig.</p><p>Pakete und Zusatztools werden zentral auf <a href="https://visualstudio.ugso-software.de/?lang=de" target="_blank" rel="noreferrer">visualstudio.ugso-software.de</a> angeboten. Diese Open-Source-Seite enthält Beschreibung und Anleitung; der Download erfolgt über den Paketkatalog.</p><p><strong>Inspiriert von den <a href="https://github.com/Sefina-DS/ioBroker.vis-2-widgets-technic" target="_blank" rel="noreferrer">ioBroker-Technic-Widgets von Sefina-DS</a>.</strong> Eigene Umsetzung für Home Assistant.</p><p>Ab <strong>Studio 0.1.203</strong> kannst du <strong>Technic 1.6.0</strong> installieren. Das Paket enthält alle sieben Widget-Typen: <strong>Window – Wall</strong>, <strong>Switch – Boolean</strong>, <strong>Dimmer – Light</strong>, <strong>Room – Overlay</strong>, <strong>Clock – Date</strong>, <strong>Thermostat – Temperature</strong> und <strong>Status – List</strong>. Version 1.6.0 kann über die Paketverwaltung als Erweiterung der bisherigen Versionen installiert werden; bestehende Widgets bleiben erhalten.</p><h2 id="status-–-list" tabindex="-1">Status – List <a class="header-anchor" href="#status-–-list" aria-label="Permalink to &quot;Status – List&quot;">​</a></h2><p><img src="'+t+'" alt="Statusliste mit Temperatur und Fensterzustand, simulierte HA-Testdaten"></p><p>Die Statusliste zeigt bis zu <strong>zehn ausschließlich lesende Statuszeilen</strong>. Standardmäßig sind <strong>0 Zeilen</strong> eingestellt; das Widget ist dann leer. Standardgröße: <strong>160 × 120 Pixel</strong>. Unter <strong>Statuszeilen</strong> stellst du Anzahl, <strong>Werte-Spalten-Versatz (90 px)</strong> und <strong>Container-Abstand links (8 px)</strong> ein. Der Versatz bestimmt die Breite der Bezeichnungsspalte; danach beginnt mit 4 px Abstand die Wertespalte. Der linke Container-Abstand kommt zum festen Innenabstand von 8 px hinzu.</p><p>Mit der Anzahl erscheinen <strong>Statuszeile [1]</strong> bis <strong>[10]</strong>. Jede Zeile erhält eine Bezeichnung und eine Home-Assistant-Entität. <strong>Zahl</strong> unterstützt Einheit, Dezimalstellen und Zahlenfarbe. <strong>Wahr / Falsch</strong> unterstützt Texte und Farben für EIN/AUS sowie zusätzliche kommagetrennte Entitäten mit <strong>UND</strong> oder <strong>ODER</strong>. Die Originalfelder <code>oid1</code> bis <code>oid10</code> entsprechen den Studio-Feldern <code>rowEntityId1</code> bis <code>rowEntityId10</code>; <code>oidsExtra1</code> bis <code>oidsExtra10</code> entsprechen <code>extraEntityIds1</code> bis <code>extraEntityIds10</code>.</p><p>Fehlende, unbekannte oder nicht verfügbare Werte bleiben <code>—</code>. Schriftgröße, Schriftart, Fettdruck und Bezeichnungsfarbe kommen aus <strong>CSS → Font und Text</strong>. Lange Bezeichnungen oder Werte werden mit Ellipse gekürzt; der Tooltip zeigt den vollständigen Text. Vergrößere für lange Einheiten die Widgetbreite; die Abbildung verwendet 240 Pixel. Bei zu vielen Zeilen wird innerhalb des Widgets gescrollt. Klicks schreiben keine HA-Zustände und blenden keine Beschriftungen aus. Alle Zeilen und Abstände bleiben im Projekt- und Widget-Export erhalten.</p><h2 id="thermostat-–-temperature" tabindex="-1">Thermostat – Temperature <a class="header-anchor" href="#thermostat-–-temperature" aria-label="Permalink to &quot;Thermostat – Temperature&quot;">​</a></h2><p><img src="'+n+'" alt="Temperaturregler nach einer Sollwertänderung; Beschriftung bleibt sichtbar"></p><p>Der Temperaturregler zeigt Soll-/Ist-Temperatur, Feuchtigkeit, Stellmotor und Kühlmodus. Standardgröße: <strong>220 × 220 Pixel</strong>, Bereich <strong>15–28</strong>, Schrittweite <strong>0,5</strong>. Unter <strong>Allgemein</strong> stellst du Bezeichnung, Anzeige, Position oben/unten, Icon-Größe und Schreibschutz ein. Unter <strong>Regler</strong> wählst du Grenzen und Schrittweite; <strong>Farben</strong> enthält EIN, AUS und Kühlen.</p><table tabindex="0"><thead><tr><th>Originalfeld</th><th>Studio-Bindung</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_temp_soll</code></td><td>Soll-Temperatur</td><td><code>climate</code> mit einzelnem Sollwert oder <code>input_number</code></td></tr><tr><td><code>oid_temp_ist</code></td><td>Ist-Temperatur</td><td>Temperatursensor oder <code>climate.current_temperature</code></td></tr><tr><td><code>oid_feuchtigkeit</code></td><td>Feuchtigkeit</td><td>Sensor in Prozent oder <code>climate.current_humidity</code></td></tr><tr><td><code>oid_stellmotor</code></td><td>Stellmotor</td><td>Sensor 0–100 %, boolescher Zustand oder <code>climate.hvac_action</code></td></tr><tr><td><code>oid_kuehlmodus</code></td><td>Kühlmodus</td><td>Boolescher Zustand oder Kühlzustand einer <code>climate</code>-Entität</td></tr></tbody></table><p>Leere Lesebindungen verwenden die passenden Attribute der Sollwert-<code>climate</code>-Entität. Bei <code>input_number</code> brauchst du separate Sensoren. Heiz-/Kühlaktivität bedeutet <strong>100 %</strong>, idle/off <strong>0 %</strong>; dies ist keine gemessene Ventilposition. Fehlende oder nicht verfügbare Werte bleiben <code>—</code>.</p><p>In der Runtime ziehst du den <strong>300°-Bogen</strong> oder bedienst den Regler per Tastatur. Erst beim Loslassen wird einmal geschrieben: <code>climate.set_temperature</code> beziehungsweise <code>input_number.set_value</code>. Der Server prüft zuvor aktuelle HA-Fähigkeiten, HA-Grenzen und beide Schrittweiten. Nicht passende Raster, unbekannte Zustände, Schreibschutz und Editorbetrieb erlauben keine Schreibaktion. Der Regler verändert nur den Sollwert; Betriebsmodus und Ein/Aus werden nicht mitgeschaltet. Nach einem HA-Fehler erscheint ein Hinweis; die Beschriftung bleibt erhalten.</p><p><img src="'+r+'" alt="Sieben-Tage-Verlauf mit Soll-/Ist-Temperatur und separater Stellmotor-Achse; simulierte Testdaten"></p><p><strong>Verlauf</strong> öffnet <strong>24 Stunden</strong> oder <strong>7 Tage</strong> aus dem <strong>Home-Assistant-Recorder</strong>. Soll und Ist verwenden die Temperaturachse, der Stellmotor die rechte Prozentachse. Die drei Farben sind unter <strong>Verlauf (HA-Recorder)</strong> einstellbar. Unbekannte Werte unterbrechen die Kurve. Der Recorder muss die ausgewählten Entitäten aufzeichnen und Daten für den gewünschten Zeitraum behalten. Die ioBroker-Einstellung <code>influxInstance</code> wird hier durch den HA-Recorder ersetzt. Alle Bindungen, Anzeigeoptionen und Farben bleiben im Projekt- und Widget-Export erhalten. Die Abbildungen stammen aus einem lokalen Test mit simulierten HA-Antworten.</p><h2 id="clock-–-date" tabindex="-1">Clock – Date <a class="header-anchor" href="#clock-–-date" aria-label="Permalink to &quot;Clock – Date&quot;">​</a></h2><p><img src="'+i+'" alt="Laufende Uhr mit Sekunden und deutschem Datum"></p><p>Die Uhr zeigt die <strong>lokale Uhrzeit und Zeitzone des Browsers</strong>. Sie benötigt keine HA-Entität. Die Anzeige aktualisiert sich jede Sekunde, ohne andere Widgets neu zu zeichnen; nach einem pausierten Browser-Tab wird die aktuelle Zeit erneut gelesen.</p><p>Unter <strong>Allgemein</strong> wählst du Nebeneinander/Untereinander, Ausrichtung links/mittig/rechts, Abstand, optionalen Hintergrund, Eckenradius und Innenabstand. Die Standardgröße beträgt 260 × 90 Pixel. Lange Datumsangaben oder große Schriften benötigen entsprechend mehr Platz; überschüssiger Inhalt bleibt scrollbar.</p><p>Unter <strong>Uhrzeit</strong> sind Anzeige, 12-/24-Stundenformat, Sekunden, Farbe, Schriftgröße und Fettdruck einstellbar. Das 12-Stundenformat verwendet AM/PM. Unter <strong>Datum</strong> bestimmst du die Anzeige, Farbe, Schriftgröße und Fettdruck getrennt.</p><p>Die Datumssprache ist unabhängig von der Studio-Sprache: Deutsch, Englisch, Französisch, Spanisch, Italienisch oder Niederländisch. Verfügbar sind Tag-Monat-Jahr, Monat-Tag-Jahr und Jahr-Monat-Tag, Punkt/Bindestrich/Schrägstrich/Leerzeichen, numerischer/kurzer/langer Monat, vier-/zweistelliges Jahr und eine optionale führende Null beim Tag. Der Wochentag kann ausgeblendet, kurz oder lang angezeigt werden. Monats- und Tagesnamen stammen aus den Sprachdaten des Browsers. Alle Optionen bleiben im Projekt- und Widget-Export erhalten.</p><h2 id="room-–-overlay" tabindex="-1">Room – Overlay <a class="header-anchor" href="#room-–-overlay" aria-label="Permalink to &quot;Room – Overlay&quot;">​</a></h2><p><img src="'+s+'" alt="Raumkachel mit sichtbarer Beschriftung und geöffneter Studio-Zielseite"></p><p>Die Raumkachel zeigt einen frei wählbaren <strong>Raumnamen</strong> und bis zu <strong>zehn Statuszeilen</strong>. Namensfarbe, Schriftgröße, Fettdruck, horizontale und vertikale Ausrichtung sowie die vier Innenabstände sind einstellbar. Standardgröße: 160 × 100 Pixel.</p><p>Unter <strong>Statuszeilen</strong> bestimmst du Anzahl, Schriftgröße und Bezeichnungsfarbe. Zeilen können untereinander oder waagerecht mit Trennzeichen und Abstand angeordnet werden. Die passenden Gruppen <strong>Statuszeile [1]</strong> bis <strong>[10]</strong> erscheinen entsprechend der Anzahl.</p><p>Jede Zeile erhält eine Bezeichnung und eine Home-Assistant-Entität. <strong>Zahl</strong> unterstützt Einheit, Dezimalstellen und Zahlenfarbe. <strong>Wahr / Falsch</strong> unterstützt Text und Farbe für EIN/AUS sowie zusätzliche kommagetrennte Entitäten mit <strong>UND</strong> oder <strong>ODER</strong>. Fehlende, unbekannte oder nicht verfügbare Werte erscheinen als <code>—</code>; sie werden nicht als ausgeschaltet gewertet. Die Daten werden nur gelesen.</p><p>Unter <strong>Klickverhalten / Popup</strong> wählst du eine vorhandene <strong>Studio-Zielseite</strong>. <strong>Popup</strong> öffnet deren Runtime in einem Dialog; <strong>Seite wechseln</strong> navigiert direkt dorthin. Eine ioBroker-View muss zuerst als Studio-Seite nachgebildet werden. Ohne gültiges Ziel öffnet die Kachel nichts; Selbstverweise und rekursive Einbettungen sind gesperrt. Im Editor dient ein Klick zur Auswahl.</p><p>Popup-Breite und -Höhe, feste X/Y-Position statt Zentrierung, Hintergrund, Rahmenfarbe, Rahmenbreite und Eckenradius sind konfigurierbar. Du kannst das Schließen bei Klick außerhalb, den Schließen-Button und das automatische Schließen nach Sekunden einstellen (<code>0</code> = aus). <strong>Escape</strong> schließt immer. Das Popup bleibt bei Live-Aktualisierungen geöffnet; die Beschriftung bleibt sichtbar. Beim Seitenwechsel oder Entfernen der Kachel schließt der Dialog. Die Größe wird auf den Bildschirm begrenzt. Alle Einstellungen bleiben im Projekt- und Widget-Export erhalten.</p><h2 id="installieren" tabindex="-1">Installieren <a class="header-anchor" href="#installieren" aria-label="Permalink to &quot;Installieren&quot;">​</a></h2><p>Lade <a href="https://visualstudio.ugso-software.de/?kind=widget&amp;lang=de" target="_blank" rel="noreferrer">ugso.technic.wg</a> herunter. Öffne <strong>Einstellungen → Widget-Pakete → Lokales .wg / .wg.zip installieren</strong> und wähle die Datei. Nach dem Neuladen erscheint das Set mit einer automatisch vergebenen freien Farbe. Es bleibt unabhängig von den integrierten Widgets und von Wetter und Heizung.</p><p>Der <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_grafik_visual_studio/packages/technic" target="_blank" rel="noreferrer">Quellcode und reproduzierbare Paketbau</a> sind öffentlich. Das Downloadpaket enthält <code>README.md</code> und <code>LICENSE.txt</code>, einschließlich des vollständigen MIT-Lizenztextes und des Herkunftshinweises <code>Copyright (c) 2026 Sefina-DS</code>.</p><h2 id="window-–-wall" tabindex="-1">Window – Wall <a class="header-anchor" href="#window-–-wall" aria-label="Permalink to &quot;Window – Wall&quot;">​</a></h2><p>Unter <strong>Allgemein</strong> stellst du Bezeichnung, <strong>Bezeichnung anzeigen</strong>, Position oben/unten, Icon-Größe (10–100 %), Griff links/rechts und Icon-Farbe ein. Die Standardgröße beträgt 120 × 160 Pixel. <strong>Schreibgeschützt</strong> sperrt die Bedienung.</p><p>Unter <strong>Datenpunkte</strong> gibt es drei unabhängige HA-Bindungen:</p><table tabindex="0"><thead><tr><th>Originalfeld</th><th>Studio-Feld</th><th>Home Assistant</th></tr></thead><tbody><tr><td><code>oid_kontakt</code></td><td>Öffnungskontakt: Entität</td><td>beispielsweise <code>binary_sensor.fenster_garage</code>; <code>on</code> bedeutet offen</td></tr><tr><td><code>oid_rollo</code></td><td>Rollo: cover-Entität</td><td>beispielsweise <code>cover.rollo_garage</code>; liest <code>current_position</code></td></tr><tr><td><code>oid_modus</code></td><td>Modus: Entität</td><td>beispielsweise <code>input_boolean.rollo_manuell</code>; aus = Automatik, ein = Manuell</td></tr></tbody></table><p>Jede Bindung besitzt eine eigene Invertierung. <strong>Rollo invertieren</strong> dreht Anzeige und Schreibwert um (<code>100 − Position</code>). Im normalen Betrieb bedeutet 0 geschlossen und 100 offen. Ein unbekannter Wert bleibt auch nach Invertierung unbekannt. Der Kontakt wird ausschließlich gelesen. Ein optionales <strong>A/M</strong>-Symbol zeigt den Modus; <code>?</code> zeigt einen unbekannten Modus.</p><p><img src="'+o+'" alt="Installiertes Technic-Set und HA-Bindungen im Editor"></p><h2 id="bedienung" tabindex="-1">Bedienung <a class="header-anchor" href="#bedienung" aria-label="Permalink to &quot;Bedienung&quot;">​</a></h2><p>In der Runtime öffnet ein Klick auf das Fenster einen Dialog mit Positionsregler, Schnellwerten <strong>0 / 25 / 50 / 75 / 100 %</strong> und optionalem Moduswechsel. Bedienung ist auch mit Tastatur möglich; Escape oder <strong>Schließen</strong> beendet den Dialog. Die Rollo-Aktion verwendet ausschließlich <code>cover.set_cover_position</code> für die ausgewählte Entität. Verfügbare Positionssteuerung (<code>supported_features</code> mit SET_POSITION) wird vor dem Schreiben geprüft. Der Modus schreibt nur an verfügbare <code>input_boolean</code>- oder <code>switch</code>-Entitäten. Ein Sensor bleibt eine Anzeige.</p><p>Der Modus-Helfer bildet nur den Schalter ab: Die eigentliche Rollo-Automatik musst du in Home Assistant einrichten. Es wird keine Automatisierung erzeugt oder deaktiviert. Fehlgeschlagene Aktionen zeigen einen Hinweis und lassen einen erneuten Versuch zu; ausstehende Aktionen werden nicht doppelt gesendet.</p><p><img src="'+d+'" alt="Runtime-Dialog mit Rolloposition und Moduswechsel"></p><h2 id="switch-–-boolean" tabindex="-1">Switch – Boolean <a class="header-anchor" href="#switch-–-boolean" aria-label="Permalink to &quot;Switch – Boolean&quot;">​</a></h2><p>Der Schalter entspricht den Einstellmöglichkeiten von <code>tplTechnicSchalterBoolean</code>. Standard: <strong>Device</strong>, Bezeichnung sichtbar unten, 120 × 160 Pixel, Power-Symbol bei 80 %, Farbe EIN <code>#2dd4b0</code>, Farbe AUS <code>#5f8f8a</code>.</p><p><strong>Datenpunkt (EIN/AUS)</strong> bindet die HA-Entität. <strong>Werttyp → Wahr / Falsch</strong> liest <code>on</code>/<code>off</code> und schaltet verfügbare <code>switch</code>, <code>light</code> oder <code>input_boolean</code> über <code>turn_on</code>/<code>turn_off</code>. <strong>0 / 1</strong> liest ausschließlich 0 und 1 und schreibt Zahlenwerte an einen <code>input_number</code>-Helfer. Dessen Grenzen und Schrittweite müssen beide Werte zulassen. Sensoren bleiben Anzeigen; unbekannte, fehlende oder nicht verfügbare Zustände sind nicht schaltbar.</p><p><strong>Icon auswählen</strong> bietet alle 16 Symbolarten: Auswahl, Desktop-PC, Power, Bettlampe, Hängelampe, runde Hängelampe, Schreibtischlampe, Spots, RGB-LED-Streifen, Tischlampe, Link, Lüfter, Schlüssel, Smartphone, Steckdose und TV. Es sind eigene geometrische SVG-Zeichnungen, keine übernommenen Grafik-Traces. Farbe EIN/AUS und Größe sind einstellbar. „Auswahl“ zeigt den Haken nur bei EIN.</p><p>Ein Klick auf das Symbol schaltet in der Runtime; die Bezeichnung bleibt sichtbar. Tastaturbedienung mit Tab und Enter/Leertaste ist möglich. <strong>Schreibgeschützt</strong> sperrt Änderungen. Laufende Aktionen werden nicht doppelt gesendet; Fehler zeigen einen Hinweis und erlauben einen erneuten Versuch. <strong>EIN (Vorschau)</strong> gilt nur ungebunden im Editor. Alle Einstellungen bleiben im Projekt und Export erhalten.</p><p><img src="'+a+'" alt="Schalter nach dem Einschalten mit sichtbarer Beschriftung"></p><h2 id="dimmer-–-light" tabindex="-1">Dimmer – Light <a class="header-anchor" href="#dimmer-–-light" aria-label="Permalink to &quot;Dimmer – Light&quot;">​</a></h2><p>Entspricht den Optionen von <code>tplTechnicReglerLicht</code>: Bezeichnung <strong>Light</strong>, sichtbar unten, Icon-Größe 80 %, 160 × 200 Pixel. <strong>Farbe EIN</strong> ist <code>#2ecfbf</code>, <strong>Farbe AUS</strong> <code>#5f8f8a</code>, <strong>Regler-Hintergrund</strong> <code>#0d1820</code>. Größe, Farben und Beschriftungsposition sind einstellbar; die Darstellung ist eine eigene SVG-Umsetzung.</p><p><strong>Ein/Aus: Entität</strong> akzeptiert <code>light</code>, <code>switch</code> oder <code>input_boolean</code>. <strong>Helligkeit: Entität (0–100)</strong> akzeptiert eine dimmbare <code>light</code>-Entität oder einen <code>input_number</code>-Helfer. Für ein gewöhnliches HA-Licht trägst du <strong>dieselbe light-Entität in beide Felder</strong> ein. Der Host rechnet das HA-Attribut <code>brightness</code> von 0–255 in Prozent um. Bei AUS zeigt er 0 %. Ein Zahlenhelfer sollte min = 0, max = 100 und step = 1 haben. Sensoren können Werte anzeigen, werden aber nicht beschrieben.</p><p><strong>Ein/Aus mit Helligkeit verknüpfen</strong> ist standardmäßig aktiv: EIN setzt 100 %, AUS setzt 0 %, Dimmen über 0 schaltet ein. Beide Bindungen müssen verfügbar und schreibbar sein. Bei derselben light-Entität wird ein einzelner HA-Aufruf erzeugt. Ohne Verknüpfung bleiben getrennte Bindungen unabhängig; eine HA-Helligkeitsaktion über <code>light.turn_on</code> schaltet das betreffende Licht dennoch ein. 0 % verwendet <code>light.turn_off</code>.</p><p>Ziehe den äußeren Kreisbogen oder nutze den Schieberegler mit Tastatur. Der Wert wird während des Ziehens lokal angezeigt und erst beim Loslassen übertragen. Der mittlere Power-Knopf schaltet EIN/AUS. Die Bezeichnung bleibt sichtbar. <strong>Schreibgeschützt</strong> sperrt Aktionen; unbekannte oder nicht dimmbare Entitäten sind nicht bedienbar. Fehlende Live-Werte werden nicht durch Vorschau ersetzt. <strong>EIN (Vorschau)</strong> und <strong>Helligkeit (Vorschau)</strong> gelten nur ungebunden im Editor.</p><p>Der Host prüft alle Ziele vor dem ersten Schreibvorgang. Bei getrennten Entitäten werden die HA-Aufrufe nacheinander ausgeführt; ein Anbieterfehler kann eine Aktion teilweise anwenden. Der Fehlerhinweis fordert zur Zustandsprüfung vor erneutem Versuch auf. Laufende Aktionen werden nicht doppelt gesendet. Die Bedienung wurde mit simulierten HA-Entitäten geprüft; reale Hardware muss separat getestet werden.</p><p><img src="'+l+'" alt="Lichtregler in der Runtime bei 50 Prozent mit sichtbarer Beschriftung"></p><h2 id="vorschau-und-export" tabindex="-1">Vorschau und Export <a class="header-anchor" href="#vorschau-und-export" aria-label="Permalink to &quot;Vorschau und Export&quot;">​</a></h2><p><strong>Vorschau</strong> bietet Fenster offen, Rolloposition und Manuell. Diese Werte gelten nur für ungebundene Anzeigen im Editor. Bei einer Bindung werden Live-Werte gelesen. In der Runtime bleiben ungebundene oder fehlende Werte unbekannt; sie werden nicht durch Vorschauwerte ersetzt. Im Editor lösen Klicks keine HA-Schaltaktionen aus.</p><p>Alle Anzeigeoptionen, drei Entitätsbindungen, Invertierungen, Vorschauwerte und Schreibschutz bleiben im Projekt und Widget-Export erhalten. Die Prüfung erfolgte mit simulierten HA-Entitäten; eine reale Rollo-Steuerung muss mit deiner Hardware getestet werden.</p>',60)])])}const D=u(b,[["render",m]]);export{E as __pageData,D as default};
